import React from 'react';
import {AbsoluteFill, Audio, Easing, Sequence, staticFile, useCurrentFrame} from 'remotion';
import {loadFont} from '@remotion/google-fonts/Inter';
import {loadFont as loadPoppins} from '@remotion/google-fonts/Poppins';
import content from './content.json';
import voTiming from './vo-timing.json';

// ---------------------------------------------------------------------------
// Editable text, colors and timing live in content.json (brand: DataEntropy
// guideline). vo-timing.json is generated by `npm run srt` from the voiceover.
// All motion is keyed to scene start frames, so moving a scene's `start`
// shifts its animations with it.
// ---------------------------------------------------------------------------

const {fontFamily} = loadFont('normal', {weights: ['400', '500', '600', '700'], subsets: ['latin']});
const FONT = `${fontFamily}, Arial, sans-serif`;
// The wordmark is set in a geometric sans (Poppins) to match the logo artwork.
const LOGO_FONT = `${loadPoppins('normal', {weights: ['700'], subsets: ['latin']}).fontFamily}, ${FONT}`;

const C = content.colors;
const FPS = content.fps;
const END = content.durationSeconds * FPS;
const S = content.scenes.map((s) => Math.round(s.start * FPS)); // scene start frames
const sceneEnd = (i: number) => (i + 1 < S.length ? S[i + 1] : END);

// Screen layout (brand safe area: 10% top, 18% bottom, 7% sides).
const SAFE = {left: 76, right: 1004};
const HEADLINE_Y = 250; // first headline baseline
const CONTENT_CY = 890; // screen y the camera centers content on (between headline and subtitles)
const SUB_BOTTOM = 1560;

// Easing: brand curve for things entering, ease-in-out for on-screen morphs,
// ease-in only for one-way exits, linear for time-based motion.
type Ease = (t: number) => number;
const EASE = {
	out: Easing.bezier(0.22, 1, 0.36, 1),
	inOut: Easing.bezier(0.645, 0.045, 0.355, 1),
	in: Easing.bezier(0.55, 0.055, 0.675, 0.19),
	linear: (t: number) => t,
};

// Keyframe track: kf(frame, [f0, f1, ...], [v0, v1, ...], easing), clamped.
// `easing` is one curve for all segments or an array with one per segment.
const kf = (f: number, frames: number[], values: number[], easing: Ease | Ease[] = EASE.inOut) => {
	if (f <= frames[0]) return values[0];
	const i = frames.findIndex((_, k) => k + 1 < frames.length && f < frames[k + 1]);
	if (i < 0) return values[values.length - 1];
	const e = Array.isArray(easing) ? easing[i] : easing;
	return values[i] + (values[i + 1] - values[i]) * e((f - frames[i]) / (frames[i + 1] - frames[i]));
};
const enter = (f: number, frames: number[], values: number[]) => kf(f, frames, values, EASE.out);
const lerp = (a: number, b: number, t: number) => a + (b - a) * t;

const mixColor = (a: string, b: string, t: number) => {
	const p = (h: string) => [1, 3, 5].map((i) => parseInt(h.slice(i, i + 2), 16));
	const [x, y] = [p(a), p(b)];
	return '#' + x.map((v, i) => Math.round(v + (y[i] - v) * t).toString(16).padStart(2, '0')).join('');
};

// "*word*" marks a highlighted word. Returns words with their highlight flag.
const parseMarked = (s: string) =>
	s.split(/(\*[^*]+\*)/).flatMap((part) => {
		const hl = part.startsWith('*');
		return part.replaceAll('*', '').split(/\s+/).filter(Boolean).map((w) => ({w, hl}));
	});
const spaced = (w: string, k: number) => (k > 0 && !/^[?.,!:;]/.test(w) ? ' ' : '') + w;

// ---------------------------------------------------------------------------
// World layout: one task board. World units equal screen pixels at zoom 1.
//   left: checklist card (request header + four rows, agent lane on the left)
//   right: three stacked tool cards        between: violet connectors
// The opening (chat bubble, reply, action buttons) happens in the same space
// and its pieces become the board.
// ---------------------------------------------------------------------------

const STEPS = content.steps;
const BUBBLE = {x: 96, y: 500, w: 560, h: 120}; // request bubble, later the card header
const CARD = {x: 96, y: 470, w: 504, h: 860, headH: 140};
const ROW_Y = [700, 880, 1060, 1240];
const LINE = ROW_Y.map((y) => y - 22); // pill, checkbox and label sit on this line
const ROW = {x: 108, w: 480, h: 156};
const LANE_X = 170; // agent lane center
const BOX_X = 266; // checkbox center
const SLOT_X = 306; // label and chip left edge
const slotY = (i: number) => LINE[i] + 62;
const TOOL = {x: 716, w: 268, h: 220, cx: 850, cy: [630, 900, 1170]};
const BTN_Y = [640, 800, 960]; // action buttons before they become tool cards
const PILL_BIG = {x: 236, y: 780, w: 180, h: 72};
const REPLY = {cx: 406, cy: 775, w: 620, h: 250};
const TRIP = {x: 540, y: 800, w: 560, h: 330};
const BUTTON = {x: 540, y: 1080, w: 460, h: 100};

const chipW = (t: string) => t.length * 15.5 + 36;

// Connector from the active row to its tool card (cubic bezier).
const connPts = (i: number) => {
	const [y1, y2] = [LINE[i], TOOL.cy[i]];
	return [[ROW.x + ROW.w, y1], [660, y1], [644, y2], [TOOL.x, y2]];
};
const bez = (p: number[][], t: number) => {
	const u = 1 - t;
	const w = [u * u * u, 3 * u * u * t, 3 * u * t * t, t * t * t];
	return {x: p.reduce((s, q, k) => s + q[0] * w[k], 0), y: p.reduce((s, q, k) => s + q[1] * w[k], 0)};
};
const arrowHead = (x: number, y: number, ang: number, size = 16) =>
	`M ${x + size * Math.cos(ang + 2.5)} ${y + size * Math.sin(ang + 2.5)} L ${x} ${y} L ${x + size * Math.cos(ang - 2.5)} ${y + size * Math.sin(ang - 2.5)}`;

// Step timing (absolute frames). Order per step: row on -> connector -> request out -> result back -> check -> tick.
const ROW_ON = [[S[5], S[7]], [S[7] + 14, S[8]], [S[8] + 14, S[10]], [S[10] + 14, S[10] + 70]];
const CHECK = [S[6] + 38, S[7] + 86, S[9] + 90, S[10] + 40];
const TICK = [S[6] + 60, S[7] + 100, S[9] + 102, S[10] + 54];
const FAIL = [S[8] + 62, S[8] + 76, S[9] + 14, S[9] + 28]; // booking card dims, then recovers
type Transit = {step: number; text: string; a: number; b: number; exit?: number};
const REQUESTS: Transit[] = [
	{step: 0, text: STEPS[0].request, a: S[5] + 34, b: S[5] + 62},
	{step: 1, text: STEPS[1].request, a: S[7] + 40, b: S[7] + 60},
	{step: 2, text: STEPS[2].request, a: S[8] + 40, b: S[8] + 60},
	{step: 2, text: STEPS[2].retryRequest ?? '', a: S[9] + 56, b: S[9] + 72},
];
const RESULTS: Transit[] = [
	{step: 0, text: STEPS[0].result, a: S[6] + 8, b: S[6] + 34},
	{step: 1, text: STEPS[1].result, a: S[7] + 66, b: S[7] + 86},
	{step: 2, text: STEPS[2].result, a: S[8] + 84, b: S[8] + 104, exit: S[9] + 6},
	{step: 2, text: STEPS[2].retryResult ?? '', a: S[9] + 74, b: S[9] + 92},
];

// Loop arrow around the board: a rounded rectangle sampled into points so a dot can run along it.
const LOOP = (() => {
	const [x0, x1, y0, y1, r] = [46, 1034, 420, 1380, 44];
	const arc = (cx: number, cy: number, a0: number) =>
		Array.from({length: 9}, (_, k) => [cx + r * Math.cos(a0 + (k * Math.PI) / 16), cy + r * Math.sin(a0 + (k * Math.PI) / 16)]);
	const pts = [[300, y0], ...arc(x1 - r, y0 + r, -Math.PI / 2), ...arc(x1 - r, y1 - r, 0), ...arc(x0 + r, y1 - r, Math.PI / 2), ...arc(x0 + r, y0 + r, Math.PI), [222, y0]];
	const len = pts.map((p, k) => (k ? Math.hypot(p[0] - pts[k - 1][0], p[1] - pts[k - 1][1]) : 0));
	const cum = len.map((_, k) => len.slice(0, k + 1).reduce((a, b) => a + b, 0));
	const total = cum[cum.length - 1];
	const at = (u: number) => {
		const d = Math.min(Math.max(u, 0), 1) * total;
		const k = Math.max(1, cum.findIndex((c) => c >= d));
		const t = (d - cum[k - 1]) / (len[k] || 1);
		return {x: lerp(pts[k - 1][0], pts[k][0], t), y: lerp(pts[k - 1][1], pts[k][1], t)};
	};
	const stations = [{x: 300, y: y0}, {x: 850, y: y0}, {x: 540, y: y1}];
	// Fraction of the loop at which the running dot reaches each station.
	const frac = stations.map((s) => {
		let best = 0;
		for (let k = 0; k <= 400; k++) {
			const [p, q] = [at(k / 400), at(best)];
			if (Math.hypot(p.x - s.x, p.y - s.y) < Math.hypot(q.x - s.x, q.y - s.y)) best = k / 400;
		}
		return best;
	});
	return {d: 'M ' + pts.map((p) => p.join(' ')).join(' L '), at, stations, frac, end: pts[pts.length - 1]};
})();
const LOOP_T = {draw: S[10] + 60, dot: S[10] + 96, dotDur: 70};

// ---------------------------------------------------------------------------
// Camera: close on the request bubble, back for the reply and the agent,
// whole board, a push-in per step, back out for the loop, then the trip card.
// ---------------------------------------------------------------------------

const camera = (f: number) => {
	const t = [S[0], S[1], S[1] + 40, S[2], S[2] + 36, S[3], S[3] + 36, S[5], S[5] + 30, S[7], S[7] + 26, S[8], S[8] + 26, S[10], S[10] + 36, S[11], S[11] + 36];
	return {
		x: kf(f, t, [376, 376, 440, 440, 540, 540, 540, 540, 540, 540, 540, 540, 540, 540, 540, 540, 540]),
		y: kf(f, t, [660, 660, 810, 810, 800, 800, 890, 890, 780, 780, 890, 890, 1010, 1010, 900, 900, 890]),
		s: kf(f, t, [1.25, 1.25, 1, 1, 1, 1, 1, 1, 1.04, 1.04, 1.04, 1.04, 1.04, 1.04, 0.86, 0.86, 1]),
	};
};

// ---------------------------------------------------------------------------
// Components
// ---------------------------------------------------------------------------

// A stroke that draws itself (one technique per stroke: pathLength + dash offset).
const Draw: React.FC<{d: string; p: number; stroke: string; w?: number; o?: number}> = ({d, p, stroke, w = 5, o = 1}) => (
	<path d={d} fill="none" stroke={stroke} strokeWidth={w} strokeLinecap="round" strokeLinejoin="round"
		pathLength={1} strokeDasharray="1 1" strokeDashoffset={1 - p} opacity={p > 0.001 ? o : 0} />
);

const Chip: React.FC<{x: number; y: number; text: string; o?: number}> = ({x, y, text, o = 1}) => {
	const w = chipW(text);
	return (
		<g opacity={o}>
			<rect x={x - w / 2} y={y - 23} width={w} height={46} rx={14} fill={C.card} stroke={C.navy} strokeWidth={4} />
			<text x={x} y={y + 10} fontSize={28} fontWeight={600} textAnchor="middle" fill={C.navy}>{text}</text>
		</g>
	);
};

// The request: a chat bubble that types in, then becomes the checklist header.
const RequestBubble: React.FC<{f: number}> = ({f}) => {
	const o = enter(f, [S[0] + 5, S[0] + 25], [0, 1]);
	const rise = enter(f, [S[0] + 5, S[0] + 25], [24, 0]);
	const m = kf(f, [S[3] + 4, S[3] + 34], [0, 1]);
	const y = lerp(BUBBLE.y, CARD.y, m) + rise;
	const w = lerp(BUBBLE.w, CARD.w, m);
	const h = lerp(BUBBLE.h, CARD.headH, m);
	const chars = Math.floor(kf(f, [S[0] + 22, S[0] + 62], [0, content.request.length], EASE.linear));
	const send = enter(f, [S[0] + 62, S[0] + 80], [0, 1]);
	const sendO = kf(f, [S[3], S[3] + 10], [1, 0], EASE.in);
	const ax = BUBBLE.x + BUBBLE.w - 62;
	const ay = y + h / 2;
	return (
		<g opacity={o}>
			<rect x={BUBBLE.x} y={y} width={w} height={h} rx={20} fill={mixColor(C.card, C.lavenderTint, m)} stroke={C.navy} strokeWidth={5}
				filter={m < 0.5 ? 'url(#soft)' : undefined} />
			<text x={BUBBLE.x + 32} y={ay + 14} fontSize={40} fontWeight={700} fill={C.navy}>{content.request.slice(0, chars)}</text>
			<g opacity={sendO}>
				<Draw d={`M ${ax - 18} ${ay} H ${ax + 18} ${arrowHead(ax + 18, ay, 0, 15)}`} p={send} stroke={C.violet} w={5} />
			</g>
		</g>
	);
};

// Scene 2: the chatbot's reply is only text. In scene 3 it folds down into the Agent pill,
// which then travels down the agent lane, one row per step.
const AgentPill: React.FC<{f: number}> = ({f}) => {
	const t = [S[1] + 10, S[1] + 34, S[2] + 6, S[2] + 34, S[3] + 30, S[3] + 60, S[7], S[7] + 22, S[8], S[8] + 22, S[10], S[10] + 24];
	const e = [EASE.out, ...Array(10).fill(EASE.inOut)];
	const cx = kf(f, t, [REPLY.cx, REPLY.cx, REPLY.cx, PILL_BIG.x, PILL_BIG.x, LANE_X, LANE_X, LANE_X, LANE_X, LANE_X, LANE_X, LANE_X], e);
	const cy = kf(f, t, [REPLY.cy + 24, REPLY.cy, REPLY.cy, PILL_BIG.y, PILL_BIG.y, LINE[0], LINE[0], LINE[1], LINE[1], LINE[2], LINE[2], LINE[3]], e);
	const w = kf(f, t, [REPLY.w * 0.96, REPLY.w, REPLY.w, PILL_BIG.w, PILL_BIG.w, 112, 112, 112, 112, 112, 112, 112], e);
	const h = kf(f, t, [REPLY.h * 0.96, REPLY.h, REPLY.h, PILL_BIG.h, PILL_BIG.h, 52, 52, 52, 52, 52, 52, 52], e);
	const o = enter(f, [S[1] + 10, S[1] + 34], [0, 1]);
	const pill = kf(f, [S[2] + 6, S[2] + 34], [0, 1]); // 0 = reply bubble, 1 = agent pill
	const bars = kf(f, [S[2] + 6, S[2] + 16], [1, 0], EASE.in);
	const label = enter(f, [S[2] + 26, S[2] + 38], [0, 1]);
	const glow = enter(f, [S[2] + 28, S[2] + 44], [0, 1]);
	const font = lerp(34, 26, kf(f, [S[3] + 30, S[3] + 60], [0, 1]));
	const left = REPLY.cx - REPLY.w / 2;
	return (
		<g opacity={o}>
			<rect x={cx - w / 2 - 14} y={cy - h / 2 - 14} width={w + 28} height={h + 28} rx={h / 2 + 14} fill={C.lavender} opacity={glow * 0.85} filter="url(#blur)" />
			<rect x={cx - w / 2} y={cy - h / 2} width={w} height={h} rx={lerp(20, h / 2, pill)} fill={mixColor(C.card, C.navy, pill)} stroke={C.navy} strokeWidth={5}
				filter={pill < 0.5 ? 'url(#soft)' : undefined} />
			{/* The reply's lines of text, written at a steady pace (bars, so no extra words on screen). */}
			{[540, 470, 520, 360].map((bw, k) => (
				<rect key={k} x={left + 40} y={REPLY.cy - 83 + k * 50} height={16} rx={8} fill={C.navy} opacity={bars}
					width={bw * kf(f, [S[1] + 34 + k * 9, S[1] + 46 + k * 9], [0, 1], EASE.linear)} />
			))}
			<text x={cx} y={cy + font * 0.36} fontSize={font} fontWeight={700} textAnchor="middle" fill="#fff" opacity={label}>{content.labels.agent}</text>
		</g>
	);
};

// Scene 2: a bracket under the empty checkboxes: nothing got booked.
const NotBooked: React.FC<{f: number}> = ({f}) => {
	const out = kf(f, [S[2], S[2] + 10], [1, 0], EASE.in);
	const label = enter(f, [S[1] + 84, S[1] + 100], [0, 1]);
	return (
		<g opacity={out}>
			<Draw d="M 236 1034 V 1050 Q 236 1064 250 1064 H 502 Q 516 1064 516 1050 V 1034" p={enter(f, [S[1] + 70, S[1] + 90], [0, 1])} stroke={C.navy} />
			<text x={376} y={1118 + (1 - label) * 24} fontSize={32} fontWeight={500} textAnchor="middle" fill={C.navy} opacity={label}>{content.labels.notBooked}</text>
		</g>
	);
};

// Scene 3: violet arms from the agent to its three actions.
const Arms: React.FC<{f: number}> = ({f}) => (
	<g>
		{BTN_Y.map((by, i) => {
			const p = Math.min(enter(f, [S[2] + 34 + i * 8, S[2] + 54 + i * 8], [0, 1]), kf(f, [S[3], S[3] + 10], [1, 0], EASE.in));
			const x0 = PILL_BIG.x + PILL_BIG.w / 2;
			return <Draw key={i} d={`M ${x0} ${PILL_BIG.y} C 520 ${PILL_BIG.y}, 600 ${by}, ${TOOL.cx - 60} ${by}`} p={p} stroke={C.violet} />;
		})}
	</g>
);

const ICONS = [
	['M 68 44 A 24 24 0 1 1 20 44 A 24 24 0 1 1 68 44', 'M 62 62 L 84 84'], // magnifier
	['M 28 24 H 72 A 10 10 0 0 1 82 34 V 72 A 10 10 0 0 1 72 82 H 28 A 10 10 0 0 1 18 72 V 34 A 10 10 0 0 1 28 24 Z', 'M 18 46 H 82', 'M 36 14 V 30', 'M 64 14 V 30'], // calendar page
	['M 16 24 V 80', 'M 16 66 H 84 V 80', 'M 38 66 V 52 H 72 A 12 12 0 0 1 84 64 V 66'], // bed
];

// A tool: a round action button in scene 3 that grows into a labelled tool card in scene 5.
const ToolCard: React.FC<{f: number; i: number}> = ({f, i}) => {
	const appear = enter(f, [S[2] + 40 + i * 8, S[2] + 58 + i * 8], [0, 1]);
	const m = kf(f, [S[4] + 4, S[4] + 34], [0, 1]); // all three together, so they never overlap mid-move
	const cy = lerp(BTN_Y[i], TOOL.cy[i], m);
	const w = lerp(120, TOOL.w, m);
	const h = lerp(120, TOOL.h, m);
	const draw = enter(f, [S[2] + 52 + i * 8, S[2] + 76 + i * 8], [0, 1]);
	const soft = enter(f, [S[4] + 34 + i * 8, S[4] + 50 + i * 8], [0, 1]);
	const label = enter(f, [S[4] + 30 + i * 8, S[4] + 46 + i * 8], [0, 1]);
	// Outline turns violet while this tool is in use; the booking card dims when its first attempt fails.
	const active = [
		kf(f, [S[5] + 26, S[5] + 38, S[7], S[7] + 10], [0, 1, 1, 0]),
		kf(f, [S[7] + 34, S[7] + 44, S[8], S[8] + 10], [0, 1, 1, 0]),
		kf(f, [S[8] + 34, S[8] + 44, FAIL[0], FAIL[1], FAIL[2], FAIL[3], S[10], S[10] + 10], [0, 1, 1, 0, 0, 1, 1, 0]),
	][i];
	const fail = i === 2 ? kf(f, FAIL, [0, 1, 1, 0]) : 0;
	const sweep = i === 0 ? kf(f, [S[5] + 62, S[5] + 72, S[5] + 82, S[5] + 92], [0, -14, 14, 0]) : 0;
	const sat = i === 1 ? enter(f, [S[7] + 58, S[7] + 70], [0, 1]) : 0;
	const k = lerp(0.8, 1.1, m); // icon scale
	const iy = cy - 30 * m;
	return (
		<g opacity={appear} transform={`translate(${TOOL.cx} ${cy}) scale(${lerp(0.96, 1, appear)}) translate(${-TOOL.cx} ${-cy})`}>
			<rect x={TOOL.cx - w / 2} y={cy - h / 2} width={w} height={h} rx={lerp(60, 20, m)} fill={mixColor(C.card, C.dimmed, fail)}
				stroke={mixColor(C.navy, C.violet, active)} strokeWidth={5} filter="url(#soft)" />
			<circle cx={TOOL.cx} cy={iy} r={56} fill={C.lavender} opacity={soft * 0.45 * (1 - fail)} />
			<g transform={`translate(${TOOL.cx} ${iy}) rotate(${sweep}) scale(${k}) translate(-50 -50)`}>
				{i === 1 && <rect x={58} y={56} width={16} height={16} rx={4} fill={C.violet} opacity={sat} />}
				{ICONS[i].map((d, n) => <Draw key={n} d={d} p={draw} stroke={C.violet} w={5 / k} />)}
				{i === 1 && [26, 42].map((x) => <rect key={x} x={x} y={56} width={16} height={16} rx={4} fill="none" stroke={C.navy} strokeWidth={4 / k} opacity={draw} />)}
				{i === 2 && (
					<g opacity={fail > 0 ? Math.min(1, fail * 3) : 0}>
						<Draw d="M 14 14 L 86 86" p={enter(f, [FAIL[0] + 8, FAIL[0] + 20], [0, 1])} stroke={C.navy} w={6 / k} />
						<Draw d="M 86 14 L 14 86" p={enter(f, [FAIL[0] + 16, FAIL[0] + 28], [0, 1])} stroke={C.navy} w={6 / k} />
					</g>
				)}
			</g>
			<text x={TOOL.cx} y={cy + 84 + (1 - label) * 24} fontSize={32} fontWeight={600} textAnchor="middle" fill={C.navy} opacity={label}>{content.tools[i]}</text>
		</g>
	);
};

// The checklist card: outline, row dividers, the active row's violet outline and the row labels.
const Checklist: React.FC<{f: number}> = ({f}) => {
	const draw = enter(f, [S[3] + 16, S[3] + 46], [0, 1]);
	return (
		<g>
			<rect x={CARD.x} y={CARD.y} width={CARD.w} height={CARD.h} rx={20} fill={C.card} fillOpacity={draw} stroke={C.navy} strokeWidth={5}
				pathLength={1} strokeDasharray="1 1" strokeDashoffset={1 - draw} opacity={draw > 0 ? 1 : 0} filter="url(#soft)" />
			{ROW_Y.slice(1).map((y) => <line key={y} x1={CARD.x + 24} x2={CARD.x + CARD.w - 24} y1={y - 90} y2={y - 90} stroke={C.grid} strokeWidth={3} strokeLinecap="round" opacity={draw} />)}
			{ROW_Y.map((y, i) => {
				const [a, b] = ROW_ON[i];
				const on = enter(f, [a, a + 14], [0, 1]);
				const off = kf(f, [b, b + 10], [1, 0], EASE.in);
				const write = kf(f, [S[3] + 52 + i * 10, S[3] + 72 + i * 10], [0, 1], EASE.linear);
				return (
					<g key={i}>
						<rect x={ROW.x} y={y - ROW.h / 2} width={ROW.w} height={ROW.h} rx={16} fill={C.lavenderTint} fillOpacity={on * 0.5} stroke={C.violet} strokeWidth={5}
							pathLength={1} strokeDasharray="1 1" strokeDashoffset={1 - on} opacity={on > 0 ? off : 0} />
						<clipPath id={`row-${i}`}>
							<rect x={SLOT_X - 4} y={LINE[i] - 30} width={290 * write} height={48} />
						</clipPath>
						<text x={SLOT_X} y={LINE[i] + 11} clipPath={`url(#row-${i})`} fontSize={32} fontWeight={600} fill={C.navy}>{STEPS[i].label}</text>
					</g>
				);
			})}
		</g>
	);
};

// Four checkboxes: three hint at work to do in scene 1, then all four become the checklist rows.
const Checkbox: React.FC<{f: number; i: number}> = ({f, i}) => {
	const a = i < 3 ? S[0] + 84 + i * 10 : S[3] + 50;
	const o = enter(f, [a, a + 18], [0, 1]);
	const rise = enter(f, [a, a + 18], [24, 0]);
	const t = [S[1] + 8, S[1] + 32, S[3] + 20 + i * 4, S[3] + 50 + i * 4];
	const x = i < 3 ? kf(f, t, [276 + i * 100, 276 + i * 100, 276 + i * 100, BOX_X]) : BOX_X;
	const y = (i < 3 ? kf(f, t, [740, 990, 990, LINE[i]]) : LINE[i]) + rise;
	const size = i < 3 ? kf(f, t, [56, 56, 56, 48]) : 48;
	const tick = enter(f, [TICK[i], TICK[i] + 16], [0, 1]);
	return (
		<g opacity={o}>
			<rect x={x - size / 2} y={y - size / 2} width={size} height={size} rx={10} fill={C.card} stroke={mixColor(C.navy, C.violet, tick)} strokeWidth={4} />
			<Draw d={`M ${x - 12} ${y + 1} L ${x - 3} ${y + 10} L ${x + 13} ${y - 9}`} p={tick} stroke={C.violet} w={6} />
		</g>
	);
};

const Connector: React.FC<{f: number; i: number}> = ({f, i}) => {
	const p = [
		kf(f, [S[5] + 12, S[5] + 30, S[7], S[7] + 10], [0, 1, 1, 0], [EASE.out, EASE.linear, EASE.in]),
		kf(f, [S[7] + 22, S[7] + 38, S[8], S[8] + 10], [0, 1, 1, 0], [EASE.out, EASE.linear, EASE.in]),
		kf(f, [S[8] + 22, S[8] + 38, S[9] + 6, S[9] + 16, S[9] + 26, S[9] + 42, S[10], S[10] + 10], [0, 1, 1, 0, 0, 1, 1, 0],
			[EASE.out, EASE.linear, EASE.in, EASE.linear, EASE.out, EASE.linear, EASE.in]),
	][i];
	const q = connPts(i);
	return <Draw d={`M ${q[0].join(' ')} C ${q[1].join(' ')}, ${q[2].join(' ')}, ${q[3].join(' ')}`} p={p} stroke={C.violet} />;
};

// A request leaves the row: an electric-purple dot runs along the connector and the request chip follows it into the tool.
const Request: React.FC<{f: number; r: Transit}> = ({f, r}) => {
	const {step, text, a, b} = r;
	if (f < a - 10 || f > b) return null;
	const t = kf(f, [a, b], [0, 1]);
	const w = chipW(text);
	const dot = bez(connPts(step), t);
	return (
		<g>
			<Chip x={lerp(SLOT_X + w / 2, TOOL.x + 70, t)} y={lerp(slotY(step), TOOL.cy[step], t)} text={text}
				o={kf(f, [a - 10, a, a + (b - a) * 0.6, b], [0, 1, 1, 0], [EASE.out, EASE.linear, EASE.in])} />
			{f >= a && <circle cx={dot.x} cy={dot.y} r={11} fill={C.purple} />}
		</g>
	);
};

// A result comes back from the tool and docks under the row label.
const Result: React.FC<{f: number; r: Transit}> = ({f, r}) => {
	const {step, text, a, b, exit} = r;
	if (f < a) return null;
	const t = kf(f, [a, b], [0, 1]);
	const w = chipW(text);
	const gone = exit === undefined ? 0 : kf(f, [exit, exit + 12], [0, 1], EASE.in);
	return <Chip x={lerp(TOOL.x + 70, SLOT_X + w / 2, t)} y={lerp(TOOL.cy[step], slotY(step), t) + gone * 16} text={text} o={enter(f, [a, a + 8], [0, 1]) * (1 - gone)} />;
};

// The agent compares the result with the step: an electric-purple bracket links the chip to the row label.
const CheckBracket: React.FC<{f: number; i: number}> = ({f, i}) => {
	const p = enter(f, [CHECK[i], CHECK[i] + 14], [0, 1]);
	const off = kf(f, [ROW_ON[i][1], ROW_ON[i][1] + 10], [1, 0], EASE.in);
	const y = LINE[i];
	return <Draw d={`M 556 ${y} H 562 Q 572 ${y} 572 ${y + 10} V ${y + 52} Q 572 ${y + 62} 562 ${y + 62} H 556`} p={p} stroke={C.purple} o={off} />;
};

// "Try again": a circular arrow draws once around the agent.
const RetryArrow: React.FC<{f: number}> = ({f}) => {
	const a = S[9];
	const p = enter(f, [a + 2, a + 26], [0, 1]);
	const out = kf(f, [a + 60, a + 70], [1, 0], EASE.in);
	// The label sits in the row's result slot, between the failed result leaving and the new request.
	const label = kf(f, [a + 14, a + 28, a + 40, a + 48], [0, 1, 1, 0], [EASE.out, EASE.linear, EASE.in]);
	const [cx, cy, r] = [LANE_X, LINE[2], 58];
	const pt = (deg: number) => [cx + r * Math.cos((deg * Math.PI) / 180), cy + r * Math.sin((deg * Math.PI) / 180)];
	const [p0, p1] = [pt(-40), pt(250)];
	return (
		<g>
			<Draw o={out} d={`M ${p0.join(' ')} A ${r} ${r} 0 1 1 ${p1.join(' ')} ${arrowHead(p1[0], p1[1], ((250 + 90) * Math.PI) / 180, 15)}`} p={p} stroke={C.purple} />
			<text x={SLOT_X} y={slotY(2) + 10} fontSize={30} fontWeight={700} fill={C.navy} opacity={label}>{content.labels.retry}</text>
		</g>
	);
};

// Plan -> act -> check -> repeat: a loop arrow around the board with three stations; a dot runs it once.
const LoopArrow: React.FC<{f: number}> = ({f}) => {
	const p = enter(f, [LOOP_T.draw, LOOP_T.draw + 30], [0, 1]);
	const out = kf(f, [S[11], S[11] + 12], [1, 0], EASE.in);
	const u = kf(f, [LOOP_T.dot, LOOP_T.dot + LOOP_T.dotDur], [0, 1], EASE.linear);
	const dot = LOOP.at(u);
	const running = f >= LOOP_T.dot && f <= LOOP_T.dot + LOOP_T.dotDur;
	return (
		<g opacity={out}>
			<Draw d={`${LOOP.d} ${arrowHead(LOOP.end[0], LOOP.end[1], 0, 18)}`} p={p} stroke={C.violet} w={6} />
			{running && <circle cx={dot.x} cy={dot.y} r={14} fill={C.purple} />}
			{LOOP.stations.map((s, k) => {
				const o = enter(f, [LOOP_T.draw + 4 + k * 8, LOOP_T.draw + 20 + k * 8], [0, 1]);
				const at = LOOP_T.dot + LOOP.frac[k] * LOOP_T.dotDur;
				const lit = kf(f, [at, at + 10], [0, 1]);
				return (
					<g key={k} opacity={o} transform={`translate(0 ${(1 - o) * 24})`}>
						<rect x={s.x - 70} y={s.y - 29} width={140} height={58} rx={29} fill={mixColor(C.card, C.violet, lit)} stroke={mixColor(C.navy, C.violet, lit)} strokeWidth={4} />
						<text x={s.x} y={s.y + 11} fontSize={32} fontWeight={600} textAnchor="middle" fill={mixColor(C.navy, '#ffffff', lit)}>{content.loop[k]}</text>
					</g>
				);
			})}
		</g>
	);
};

// Step 4's result is the trip summary: a chip on row 4 that grows into the trip card the person approves.
const TripCard: React.FC<{f: number}> = ({f}) => {
	const a = S[10] + 26;
	if (f < a) return null;
	const T = S[11];
	const text = STEPS[3].result;
	const cw = chipW(text);
	const o = enter(f, [a, a + 16], [0, 1]);
	const m = kf(f, [T + 4, T + 34], [0, 1]);
	const x = lerp(SLOT_X + cw / 2, TRIP.x, m);
	const y = lerp(slotY(3), TRIP.y, m) + (1 - o) * 24;
	const w = lerp(cw, TRIP.w, m);
	const h = lerp(46, TRIP.h, m);
	const note = enter(f, [T + 56, T + 70], [0, 1]);
	// Approve button: enters, a cursor presses it, it fills violet.
	const btn = enter(f, [T + 62, T + 80], [0, 1]);
	const cur = enter(f, [T + 90, T + 112], [0, 1]);
	const press = kf(f, [T + 114, T + 120, T + 128], [0, 1, 0]);
	const filled = kf(f, [T + 120, T + 132], [0, 1]);
	return (
		<g>
			<g opacity={o}>
				<rect x={x - w / 2} y={y - h / 2} width={w} height={h} rx={lerp(14, 20, m)} fill={C.card} stroke={C.navy} strokeWidth={lerp(4, 5, m)} filter={m > 0.5 ? 'url(#soft)' : undefined} />
				<text x={x} y={y + 10} fontSize={28} fontWeight={600} textAnchor="middle" fill={C.navy} opacity={kf(f, [T + 4, T + 14], [1, 0], EASE.in)}>{text}</text>
				{content.trip.lines.map((line, k) => {
					const lo = enter(f, [T + 30 + k * 8, T + 46 + k * 8], [0, 1]);
					const ly = TRIP.y - 62 + k * 70 + (1 - lo) * 16;
					return (
						<g key={k} opacity={lo}>
							<circle cx={TRIP.x - TRIP.w / 2 + 64} cy={ly - 14} r={9} fill={C.violet} />
							<text x={TRIP.x - TRIP.w / 2 + 96} y={ly} fontSize={40} fontWeight={600} fill={C.navy}>{line}</text>
						</g>
					);
				})}
				<text x={TRIP.x + TRIP.w / 2 - 36} y={TRIP.y + TRIP.h / 2 - 30} fontSize={24} fontStyle="italic" textAnchor="end" fill={C.muted} opacity={note}>{content.trip.note}</text>
			</g>
			<g opacity={btn} transform={`translate(${BUTTON.x} ${BUTTON.y + (1 - btn) * 24}) scale(${1 - press * 0.04})`}>
				<rect x={-BUTTON.w / 2} y={-BUTTON.h / 2} width={BUTTON.w} height={BUTTON.h} rx={20} fill={mixColor(C.card, C.violet, filled)} stroke={C.violet} strokeWidth={5} filter="url(#soft)" />
				<text y={13} fontSize={38} fontWeight={700} textAnchor="middle" fill={mixColor(C.violet, '#ffffff', filled)}>{content.trip.approve}</text>
			</g>
			{/* The person's hand cursor: fingertip lands on the button. */}
			<g opacity={cur} transform={`translate(${lerp(790, 690, cur)} ${lerp(1260, 1108, cur) + press * 6})`}>
				<path d="M 0 0 a 9 9 0 0 1 18 0 v 26 l 22 5 a 10 10 0 0 1 8 11 l -4 26 a 8 8 0 0 1 -8 7 h -26 a 10 10 0 0 1 -8 -4 l -20 -24 a 8 8 0 0 1 12 -10 l 6 6 z"
					fill={C.card} stroke={C.navy} strokeWidth={5} strokeLinejoin="round" />
			</g>
		</g>
	);
};

// Headline: left-aligned, masked reveal line by line, *words* in brand violet.
const Headline: React.FC<{f: number}> = ({f}) => (
	<>
		{content.scenes.map((sc, i) => {
			if (!sc.headline) return null;
			const a = S[i];
			const b = sceneEnd(i);
			const out = kf(f, [b - 8, b], [1, 0], EASE.in);
			if (f < a || out <= 0) return null;
			return (
				<g key={i} opacity={out}>
					{sc.headline.split('\n').map((line, li) => {
						const y = HEADLINE_Y + li * 72;
						const rise = enter(f, [a + li * 4, a + 18 + li * 4], [74, 0]);
						return (
							<g key={li}>
								<clipPath id={`hl-${i}-${li}`}>
									<rect x={0} y={y - 62} width={1080} height={80} />
								</clipPath>
								<text x={SAFE.left} y={y + rise} clipPath={`url(#hl-${i}-${li})`} fontSize={58} fontWeight={700} fill={C.navy}>
									{parseMarked(line).map(({w, hl}, k) => (
										<tspan key={k} fill={hl ? C.violet : C.navy}>{spaced(w, k)}</tspan>
									))}
								</text>
							</g>
						);
					})}
				</g>
			);
		})}
	</>
);

// Subtitles: navy bar in the lower safe area, word-group reveal synced to the voiceover.
const Subtitles: React.FC<{f: number}> = ({f}) => (
	<>
		{content.scenes.map((sc, i) => {
			const start = sc.voStart * FPS;
			const dur = ((voTiming as number[])[i] ?? 3) * FPS;
			const end = Math.min(sceneEnd(i) - 2, start + dur + 18);
			const o = kf(f, [start - 4, start + 4, end - 6, end], [0, 1, 1, 0]);
			if (o <= 0) return null;
			const words = parseMarked(sc.voiceover);
			const perLine = words.length > 7 || sc.voiceover.length > 40 ? Math.ceil(words.length / 2) : words.length;
			const lines = [words.slice(0, perLine), words.slice(perLine)].filter((l) => l.length);
			const h = 34 + lines.length * 54;
			let n = 0;
			return (
				<g key={i} opacity={o}>
					<rect x={SAFE.left} y={SUB_BOTTOM - h} width={SAFE.right - SAFE.left} height={h} rx={20} fill={C.navy} fillOpacity={0.88} />
					{lines.map((line, li) => (
						<text key={li} x={540} y={SUB_BOTTOM - h + 56 + li * 54} fontSize={40} fontWeight={600} textAnchor="middle">
							{line.map(({w, hl}, k) => {
								// Words reveal in groups of three, paced across the spoken line.
								const group = Math.floor(n++ / 3);
								const at = start + (group * 3 * dur) / words.length;
								return (
									<tspan key={k} fill={hl ? C.lavender : '#fff'} fillOpacity={enter(f, [at, at + 8], [0.25, 1])}>
										{spaced(w, k)}
									</tspan>
								);
							})}
						</text>
					))}
				</g>
			);
		})}
	</>
);

// Outro: the four ticked checkboxes slide together and stand up as the DataEntropy logo bars
// (four gradient bars above the wordmark, violet "E"), then the tagline and one CTA.
// Guideline motion: bars grow left to right, wordmark reveals after, soft violet glow.
const LOGO = {
	barW: 66,
	gap: 22,
	heights: [96, 156, 212, 276], // proportions of the logo image
	base: 700, // bar baseline (screen y)
	wordY: 832, // wordmark baseline
	wordSize: 104,
};
const Outro: React.FC<{f: number}> = ({f}) => {
	const a = S[S.length - 1];
	if (f < a) return null;
	const {barW, gap, heights, base} = LOGO;
	const symbolW = heights.length * barW + (heights.length - 1) * gap;
	const left = 540 - symbolW / 2;
	const top = base - heights[heights.length - 1];
	const seed = enter(f, [a + 8, a + 20], [0, 1]);
	const gather = kf(f, [a + 10, a + 30], [0, 1]);
	const word = enter(f, [a + 60, a + 80], [0, 1]);
	const glow = kf(f, [a + 74, a + 83, a + 92], [0, 1, 0.35]);
	const tag = enter(f, [a + 74, a + 90], [0, 1]);
	const cta = enter(f, [a + 84, a + 102], [0, 1]);
	const arrow = kf(f, [a + 98, a + 116], [0, 10], EASE.inOut);
	return (
		<g>
			<linearGradient id="logoBars" gradientUnits="userSpaceOnUse" x1={left} y1={top} x2={left + symbolW} y2={base}>
				<stop offset="0" stopColor={C.lavender} />
				<stop offset="0.55" stopColor={C.purple} />
				<stop offset="1" stopColor={C.violet} />
			</linearGradient>
			<g filter={glow > 0.05 ? 'url(#glow)' : undefined}>
				{heights.map((bh, k) => {
					// Each bar starts as a checkbox (the camera is at zoom 1 here, so world = screen), then grows.
					const g = enter(f, [a + 30 + k * 7, a + 48 + k * 7], [0, 1]);
					const w = lerp(48, barW, gather);
					const h = w + (bh - barW) * g;
					const cx = lerp(BOX_X, left + k * (barW + gap) + barW / 2, gather);
					const bottom = lerp(LINE[k] + 24, base, gather);
					return <rect key={k} x={cx - w / 2} y={bottom - h} width={w} height={h} rx={lerp(10, barW / 2, gather)} fill="url(#logoBars)" opacity={seed} />;
				})}
			</g>
			<clipPath id="wordmark">
				<rect x={540 - 400} y={LOGO.wordY - 110} width={800 * word} height={150} />
			</clipPath>
			<text x={540} y={LOGO.wordY} clipPath="url(#wordmark)" fontFamily={LOGO_FONT} fontSize={LOGO.wordSize} fontWeight={700}
				textAnchor="middle" fill={C.navy} letterSpacing={-1}>
				Data<tspan fill={C.purple}>E</tspan>ntropy
			</text>
			<text x={540} y={935 + (1 - tag) * 24} fontSize={34} fontWeight={500} textAnchor="middle" fill={C.muted} opacity={tag}>{content.brand.tagline}</text>
			<g opacity={cta} transform={`translate(0 ${(1 - cta) * 24})`}>
				<rect x={260} y={1000} width={560} height={100} rx={20} fill={C.violet} filter="url(#soft)" />
				<text x={520} y={1063} fontSize={38} fontWeight={600} textAnchor="middle" fill="#fff">{content.brand.cta}</text>
				<text x={745 + arrow} y={1063} fontSize={38} fontWeight={600} textAnchor="middle" fill="#fff">→</text>
			</g>
		</g>
	);
};

// ---------------------------------------------------------------------------

export const AiAgentsVideo: React.FC = () => {
	const f = useCurrentFrame();
	const base = camera(f);
	// A slow breathing zoom (6 s sine loop) keeps the picture alive while the narrator talks over a held frame.
	const cam = {...base, s: base.s * (1 + 0.015 * Math.sin((f / 180) * 2 * Math.PI))};
	const last = S[S.length - 1];
	const worldO = kf(f, [last, last + 18], [1, 0], EASE.in);
	const dim = kf(f, [S[11] + 4, S[11] + 22], [0, 0.72]); // the board steps back behind the trip card

	return (
		<AbsoluteFill style={{backgroundColor: C.background, fontFamily: FONT}}>
			<svg width={1080} height={1920} viewBox="0 0 1080 1920" style={{fontFamily: FONT}}>
				<defs>
					<filter id="soft" x="-30%" y="-30%" width="160%" height="170%">
						<feDropShadow dx="0" dy="10" stdDeviation="14" floodColor={C.violet} floodOpacity="0.1" />
					</filter>
					<filter id="glow" x="-50%" y="-50%" width="200%" height="200%">
						<feDropShadow dx="0" dy="0" stdDeviation="12" floodColor={C.violet} floodOpacity="0.35" />
					</filter>
					<filter id="blur" x="-50%" y="-80%" width="200%" height="260%">
						<feGaussianBlur stdDeviation="12" />
					</filter>
					<pattern id="dots" width={48} height={48} patternUnits="userSpaceOnUse">
						<circle cx={24} cy={24} r={2} fill={C.grid} />
					</pattern>
					<linearGradient id="worldFade" x1="0" y1="0" x2="0" y2="1920" gradientUnits="userSpaceOnUse">
						<stop offset={340 / 1920} stopColor="#fff" stopOpacity={0} />
						<stop offset={400 / 1920} stopColor="#fff" />
						<stop offset={1390 / 1920} stopColor="#fff" />
						<stop offset={1440 / 1920} stopColor="#fff" stopOpacity={0} />
					</linearGradient>
					<mask id="worldMask" maskUnits="userSpaceOnUse" x={0} y={0} width={1080} height={1920}>
						<rect width={1080} height={1920} fill="url(#worldFade)" />
					</mask>
					<radialGradient id="lavGlow" cx="0.85" cy="0.1" r="0.7">
						<stop offset="0" stopColor={C.lavender} stopOpacity={0.35} />
						<stop offset="1" stopColor={C.lavender} stopOpacity={0} />
					</radialGradient>
				</defs>
				<rect width={1080} height={1920} fill="url(#lavGlow)" />
				<g mask="url(#worldMask)">
				<g opacity={worldO} transform={`translate(${540 - cam.x * cam.s} ${CONTENT_CY - cam.y * cam.s}) scale(${cam.s})`}>
					<rect x={-1500} y={-1500} width={4000} height={5000} fill="url(#dots)" />
					<Checklist f={f} />
					<RequestBubble f={f} />
					<NotBooked f={f} />
					<Arms f={f} />
					{[0, 1, 2].map((i) => <Connector key={i} f={f} i={i} />)}
					{[0, 1, 2].map((i) => <ToolCard key={i} f={f} i={i} />)}
					{[0, 1, 2, 3].map((i) => <Checkbox key={i} f={f} i={i} />)}
					{[0, 1, 2, 3].map((i) => <CheckBracket key={i} f={f} i={i} />)}
					<AgentPill f={f} />
					<RetryArrow f={f} />
					{RESULTS.map((r, k) => <Result key={k} f={f} r={r} />)}
					{REQUESTS.map((r, k) => <Request key={k} f={f} r={r} />)}
					<LoopArrow f={f} />
					<rect x={-1500} y={-1500} width={4000} height={5000} fill={C.background} opacity={dim} />
					<TripCard f={f} />
				</g>
				</g>
				<Outro f={f} />
				<Headline f={f} />
				<Subtitles f={f} />
			</svg>
			{content.scenes.map((sc, i) => (
				<Sequence key={i} from={Math.round(sc.voStart * FPS)}>
					<Audio src={staticFile(`vo/scene-${i + 1}.wav`)} />
				</Sequence>
			))}
			<Audio src={staticFile('music.wav')} />
		</AbsoluteFill>
	);
};
